import { ABILITY_TYPE_KEYWORDS, abilityFeaturePillClass, abilityFeaturePillKeywords, abilityFeaturePillLabel, abilityTypeClass, activeAbilityKeywords, canonicalAbilityType } from '../rules/abilityPresentation'
import { THREAT_BANDS, threatBandScoreLabel } from '../rules/threatLevel'
import { narrativeRuleDetail, sourceNarrativeDescription } from '../rules/narrativeRules'

const route=useRoute()
const {measurement}=useSettings()
const slug=computed(()=>String(route.params.slug||''))
const page=computed(()=>findRulePage(slug.value))
const canonicalSlug=computed(()=>canonicalRuleSlug(slug.value))
const rawSourceSections=computed(()=>page.value?resolveSourceSections(page.value):[])
const ruleNavigation=computed(()=>rulePageNavigation(canonicalSlug.value))
const loreAttunedPreview=ref(false)
watch(slug,value=>{loreAttunedPreview.value=false;if(value)recordRecentRule(value)},{immediate:true})

type CreationAttributeRanks=Record<AttributeId,number>
function freshCreationAttributeRanks(){return Object.fromEntries(attributes.map(attribute=>[attribute.id,1])) as CreationAttributeRanks}
const creationAttributeRanks=ref<CreationAttributeRanks>(freshCreationAttributeRanks())
const creationAttributePointsRemaining=computed(()=>5-attributes.reduce((spent,attribute)=>spent+(creationAttributeRanks.value[attribute.id]-1),0))
function adjustCreationAttribute(id:AttributeId,amount:number){
  const current=creationAttributeRanks.value[id]
  if(amount>0&&(current>=3||creationAttributePointsRemaining.value<=0))return
  if(amount<0&&current<=1)return
  creationAttributeRanks.value={...creationAttributeRanks.value,[id]:current+amount}
}
function creationAttributeModifier(id:AttributeId){return rankModifier(creationAttributeRanks.value[id])}
function creationAttributeSecondary(id:AttributeId){
  const rank=creationAttributeRanks.value[id],modifier=rankModifier(rank)
  if(id==='agility')return[{label:'Accuracy',value:String(rank)},{label:'Aim',value:String(modifier)},{label:'Speed',value:`2 + ${modifier} = ${modifier+2}`}]
  if(id==='might')return[{label:'Fury',value:String(rank)},{label:'Brawl',value:String(modifier)}]
  if(id==='hide')return[{label:'Guts',value:String(rank)},{label:'Ward',value:String(modifier)}]
  if(id==='lore')return[{label:'Power',value:String(rank)},{label:'Control',value:String(modifier)}]
  return[{label:'Heart',value:String(rank)},{label:'Spirit',value:String(modifier)}]
}
watch(slug,(value,previous)=>{if(value==='character-creation'||previous==='character-creation')creationAttributeRanks.value=freshCreationAttributeRanks()})

const bannerModules=import.meta.glob('../assets/rule-banners/*.{png,PNG,jpg,JPG,jpeg,JPEG,webp,WEBP}',{eager:true,query:'?url',import:'default'}) as Record<string,string>
function bannerKey(value:string){const key=value.replace(/[^a-z0-9]+/gi,'').toLowerCase();return key==='athromundas'?'anthromundas':key}
function bannerStem(path:string){return (path.split('/').pop()||'').replace(/\.[^.]+$/,'').replace(/^banner[-_ ]*/i,'')}
const currentBanner=computed(()=>{
  if(!page.value)return''
  const wanted=Array.from(new Set([page.value.title,page.value.slug,page.value.title.replace(/^Lore of /i,''),page.value.slug.replace(/^lore[-_]?/i,'')].map(bannerKey).filter(Boolean)))
  const entry=Object.entries(bannerModules).find(([path])=>{
    const stem=bannerKey(bannerStem(path));return wanted.some(key=>stem===key||stem.endsWith(key)||key.endsWith(stem))
  })
  return entry?.[1]||''
})
function abilityTypes(values:string[]){return Array.from(new Set(traitKeywords(values).map(canonicalAbilityType).filter(value=>ABILITY_TYPE_KEYWORDS.has(value))))}
function manaCostFromRule(text:string){const match=text.match(/\bCOST:\s*\[?([0-9]+)\]?\s*mana/i);return match?Number(match[1]):null}

function displayText(value:string){return formatMeasurementText(value.replace(/\bProwess\b/g,'Agility').replace(/\bprowess\b/g,'agility'),measurement.value)}
function isDialogue(value:string){return /\b(?:Watcher|Player|Selu):/.test(value)}
function dialogueParts(value:string){
  const parts:Array<{actor:string;text:string}>=[]
  const rx=/(Watcher|Player|Selu):\s*[“"]?([^”"]+)[”"]?/g
  let match:RegExpExecArray|null
  while((match=rx.exec(value)))parts.push({actor:match[1],text:match[2].trim()})
  return parts
}
function keywordParts(value:string){if(!/^KEYWORDS?:/i.test(value.trim()))return[];return value.split(':',2)[1].split('|').map(item=>item.trim()).filter(Boolean)}
function keywordPartsForBlock(block:RuleSourceBlock){return block.type==='paragraph'?keywordParts(block.text):[]}
function isExampleHeading(value:string){return /example/i.test(value)}

const sourceSections=computed(()=>{
  const entries=rawSourceSections.value
  if(page.value?.loreHeading){
    const entry=entries[0];if(!entry)return[]
    const headings=new Set(loreNavigation.map(item=>item.heading))
    const blocks=entry.section.blocks
    const start=blocks.findIndex(block=>block.type==='paragraph'&&block.text.trim()===page.value?.loreHeading)
    if(start<0)return[]
    let end=blocks.length
    for(let index=start+1;index<blocks.length;index++){const block=blocks[index];if(block.type==='paragraph'&&headings.has(block.text.trim())){end=index;break}}
    const section:RuleSourceSection={heading:page.value.loreHeading,blocks:blocks.slice(start+1,end)}
    return[{...entry,section}]
  }
  if(canonicalSlug.value==='to-damage')return entries.filter(entry=>!/^DAMAGE\s*[–-]\s*GUTS\s*=\s*TOTAL DAMAGE$/i.test(displayText(entry.section.heading).trim()))
  return entries
})

const loreIndex=computed(()=>loreNavigation.findIndex(item=>item.slug===canonicalSlug.value))
const breadcrumbSection=computed(()=>{
  if(loreIndex.value>=0||quickReferencePages.some(item=>item.slug===canonicalSlug.value))return'References'
  if(findExternalMonster(canonicalSlug.value))return'The Watcher'
  return findRuleCategory(canonicalSlug.value)?.title||'Rules'
})
const breadcrumbParent=computed(()=>findRuleParentPage(canonicalSlug.value)||null)
const layoutParent=computed(()=>{
  if(breadcrumbSection.value==='References')return{label:'References',path:'/rules'}
  return breadcrumbParent.value&&breadcrumbParent.value.slug!==page.value?.slug?{label:breadcrumbSection.value,path:`/rules/read/${breadcrumbParent.value.slug}`}:null
})
const currentCategoryLanding=computed(()=>ruleCategories.find(category=>category.landing.slug===canonicalSlug.value)||null)
const landingEntries=computed(()=>currentCategoryLanding.value?.pages||[])
function labeledParagraph(value:string){const text=displayText(value).trim();const match=text.match(/^([^:]{2,45}):\s+(.+)$/);return match?{label:match[1],body:match[2]}:{label:'',body:text}}
function bulletParts(value:string){const parts=displayText(value).split(/\s*•\s*/).map(part=>part.trim()).filter(Boolean);return parts.length>1?parts:[]}
function optionalTextParts(value:string){const match=value.match(/^(.*?)(\s*\(optional\))(.*)$/i);return match?[{text:match[1],optional:false},{text:match[2],optional:true},{text:match[3],optional:false}]:[{text:value,optional:false}]}
function singleCellText(block:RuleSourceBlock){return block.type==='table'&&block.rows.length===1&&block.rows[0].length===1?displayText(block.rows[0][0]).trim():''}

const currentSpecies=computed(()=>canonicalSlug.value.startsWith('species-')?speciesData.find(item=>`species-${item.name.toLowerCase()}`===canonicalSlug.value)||null:null)
const currentMonster=computed(()=>findExternalMonster(canonicalSlug.value)||null)
const monsterGroups=computed(()=>monsterCategories.map(category=>{
  const monsters=externalMonsters.filter(monster=>monster.category===category.name)
  const parents=monsters.filter(monster=>!monster.group)
  const families=parents.map(parent=>({parent,children:monsters.filter(monster=>monster.group===parent.name)}))
  const groupedNames=new Set(families.flatMap(family=>[family.parent.name,...family.children.map(child=>child.name)]))
  for(const orphan of monsters.filter(monster=>!groupedNames.has(monster.name)))families.push({parent:orphan,children:[]})
  return{category,monsters,families}
}))
const talentSections=ruleSourceDocuments.talents.sections.filter(section=>section.heading!=='Overview'&&section.heading!=='TALENTS'&&!section.heading.startsWith('KEYWORDS'))
function talentRuleText(name:string){const section=talentSections.find(item=>talentNameMatches(item.heading,name));return section?.blocks.filter(block=>block.type==='paragraph').map(block=>block.type==='paragraph'?block.text:'').join(' ')||''}
function talentRuleKeywords(name:string){const match=talentRuleText(name).match(/\bKEYWORDS?:\s*(.+)$/i);return activeAbilityKeywords(match?[match[1]]:[])}
function talentCategory(name:string){return classifyTalent(name,talentRuleText(name),talentRuleKeywords(name))}
const talentRuleGroups=computed(()=>TALENT_CATEGORIES.map(category=>({category,talents:talentSections.map(section=>canonicalTalentName(section.heading)).filter(name=>talentCategory(name)===category)})).filter(group=>group.talents.length))
const spellLoreBySlug:Record<string,string>={'lore-invocation':'Invocation','lore-flames':'Flames','lore-frost':'Frost','lore-hallows':'Hallows','lore-harmony':'Harmony','lore-life':'Life','lore-oath':'Oath','lore-wilds':'Wilds'}
const currentSpellLore=computed(()=>spellLoreBySlug[canonicalSlug.value]||'')
const currentLoreSpells=computed(()=>currentSpellLore.value?(loreSpells[currentSpellLore.value]||[]):[])
function spellRuleDetail(name:string){return spellDetails[name]}
const canPreviewLoreAttunement=computed(()=>Boolean(currentSpellLore.value&&currentSpellLore.value!=='Invocation'))
function displayedLoreCost(name:string){const detail=spellRuleDetail(name);if(!detail)return'Variable';return spellCostLabel({name,lore:detail.lore,baseCost:detail.manaCost,attunedLore:loreAttunedPreview.value&&canPreviewLoreAttunement.value?currentSpellLore.value:''})}
function spellLoreClass(name:string){return `spell-lore-${String(spellDetails[name]?.lore||'invocation').toLowerCase()}`}
function isSignatureSpell(name:string){return SIGNATURE_SPELLS.has(name)}
const currentLoreResistance=computed(()=>currentSpellLore.value&&currentSpellLore.value!=='Invocation'?loreElementalResistance[currentSpellLore.value as keyof typeof loreElementalResistance]||'':'')
const spellKeywordSource=computed(()=>sectionByHeading('winds-of-magic','SPELL KEYWORDS'))
const spellMagicKeywordText=computed(()=>sectionParagraphs(spellKeywordSource.value).find(text=>/^MAGIC\b/i.test(text))||'')
const spellKeywordCards=computed(()=>{const blocks=spellKeywordSource.value?.blocks||[];return blocks.flatMap(block=>{if(block.type!=='paragraph')return[];const text=displayText(block.text);if(/^MAGIC\b/i.test(text))return[];const names=['AREA OF EFFECT','SIGNATURE','CANTRIP','ENHANCE','SUMMON','HEX'];const title=names.find(name=>text.toUpperCase().startsWith(name))||'SPELL';return[{title,text}]})})
const signatureExampleName='Immolation'
const signatureExample=computed(()=>spellDetails[signatureExampleName])
const targetingRules=[
  {title:'Line',keyword:'LINE[n]',image:targetingLineImage,text:'A Line ability creates a straight path that never bends and affects every square it touches. The user chooses the direction; the Line continues from the user until it reaches its listed maximum length or an obstacle the ability cannot pass through.',example:'LINE[10] traces a straight line exactly ten squares long in the chosen direction. Every valid character, object, or terrain feature whose square lies along that path is affected.'},
  {title:'Cone',keyword:'CONE[n]',image:targetingConeImage,text:'A Cone ability begins adjacent to the user and extends outward in a triangular pattern on the grid. Its width grows as it advances, matching the listed area size.',example:'CONE[6] starts in the square directly in front of the user and expands to a roughly triangular shape six squares long and six squares wide at its farthest edge.'},
  {title:'Orb',keyword:'ORB[n]',image:targetingOrbImage,text:'For an Orb ability, choose a valid point within the Ability’s range. The Orb expands from that square as a square-shaped area whose size is determined by the Orb number. It ignores the user’s facing.',example:'ORB[7] creates a 7×7 block of squares from the chosen point. Every valid target whose square lies inside that area, including the edges, is affected.'},
]
const combatAttackCoreActions=coreActions.filter(action=>['MELEE STRIKE','RANGE STRIKE','ARCANE COMMAND'].includes(action.name))
const instinctCoreActions=coreActions.filter(action=>action.keywords.map(canonicalAbilityType).includes('Instinct'))
const instinctTraitExamples=computed(()=>speciesData.flatMap(species=>[
  ...species.speciesTraits.map(trait=>({species:species.name,trait,kind:'Heritage' as const})),
  ...species.cultureTraits.map(trait=>({species:species.name,trait,kind:'Cultural' as const})),
]).filter(item=>traitKeywords(item.trait.keywords).map(canonicalAbilityType).includes('Instinct')&&/end of (?:the )?round/i.test(item.trait.text)).slice(0,2))
const combatEncounterSection=computed(()=>sectionByHeading('battle','ENCOUNTERS'))
const determiningPositionsSection=computed(()=>sectionByHeading('battle','DETERMINING POSITIONS'))
const squaresMeasurementsSection=computed(()=>sectionByHeading('battle','SQUARES & MEASUREMENTS'))
const initiativeSection=computed(()=>sectionByHeading('battle','INITIATIVE ORDER'))
const roundsTurnsSection=computed(()=>sectionByHeading('battle','ROUNDS & TURNS'))
const takingTurnSection=computed(()=>sectionByHeading('battle','TAKING YOUR TURN'))
const manaSection=computed(()=>sectionByHeading('battle','MANA'))
const renewTheHeartAction=coreActions.find(action=>action.name==='RENEW THE HEART')!
function traitKeywords(values:string[]){return activeAbilityKeywords(values)}
function skillTreeName(block:RuleSourceBlock){if(block.type!=='table'||block.rows.length<2)return'';const row=block.rows[1];return row.length===1&&/Skill Tree$/i.test(row[0])?displayText(row[0]):''}
function skillTreeRows(block:RuleSourceBlock){return block.type==='table'?block.rows.slice(2):[]}
function skillTreeTone(name:string){return name.toLowerCase().split(' ')[0]||'skill'}
function isBuildingSeluTable(block:RuleSourceBlock){const text=singleCellText(block);return /^Selu(?:’s| of )/i.test(text)}
function bracketParts(value:string){const text=displayText(value);const parts:Array<{text:string;bold:boolean}>=[];const rx=/(\[[+-]?\d+(?:\.\d+)?\])/g;let last=0,match:RegExpExecArray|null;while((match=rx.exec(text))){if(match.index>last)parts.push({text:text.slice(last,match.index),bold:false});parts.push({text:match[0],bold:true});last=match.index+match[0].length}if(last<text.length)parts.push({text:text.slice(last),bold:false});return parts.length?parts:[{text,bold:false}]}
function isLongNarrativeHeading(value:string){const t=displayText(value).trim();return t.startsWith('Packs, Herds, & Kinships (Optional Rule)')||t.startsWith('WATCHER’S NOTE')}
function narrativeParts(value:string){const t=displayText(value).trim();if(t.startsWith('WATCHER’S NOTE'))return{title:'WATCHER’S NOTE',body:t.replace(/^WATCHER’S NOTE\s*/,'')};const title='Packs, Herds, & Kinships (Optional Rule)';return{title,body:t.replace(title,'').trim()}}
function equipmentTableRows(block:RuleSourceBlock){if(canonicalSlug.value!=='adventuring-gear'||block.type!=='table'||block.rows.length<2||block.rows[0].length<2)return[];const headers=block.rows[0].map(displayText);return block.rows.slice(1).filter(row=>row.some(cell=>String(cell).trim())).map(row=>({name:displayText(row[0]||'Item'),fields:row.slice(1).map((cell,index)=>({label:headers[index+1]||`Value ${index+1}`,value:displayText(cell||'—')}))}))}
function characterCreationStepParts(section:RuleSourceSection){const match=section.heading.match(/^(\d+)\.\s*(.+)$/);return match?{number:match[1],title:displayText(match[2])}:null}
function isCharacterCreationStep(section:RuleSourceSection){return canonicalSlug.value==='character-creation'&&Boolean(characterCreationStepParts(section))}
function isCharacterCreationAttributeTable(section:RuleSourceSection,block:RuleSourceBlock){return canonicalSlug.value==='character-creation'&&/^5\.\s*ATTRIBUTES DISTRIBUTION$/i.test(section.heading)&&block.type==='table'&&/^Attribute$/i.test(block.rows[0]?.[0]||'')}
function characterCreationStepNumber(section:RuleSourceSection){return Number(characterCreationStepParts(section)?.number||0)}
function creationGraphicStep(section:RuleSourceSection,step:number){return canonicalSlug.value==='character-creation'&&characterCreationStepNumber(section)===step}
const creationHomelandExample=homelands.find(item=>item.name==='Willowstead')||homelands[0]
const creationFaithExample='The Dreamtide'
const creationOathExample=oaths.find(item=>item[0]==='Balance')||oaths[0]
const exchangeExampleStartingSp=377/WP_PER_SP
type DeedEntry={name:string;flavor:string;objective:string;reward:string;keywords:string[];rollRange?:string}
const sparkRuleSections=computed(()=>ruleSourceDocuments.sparks.sections.filter(section=>section.heading!=='Overview'&&section.blocks.length))
const sparkWhatSections=computed(()=>sparkRuleSections.value.filter(section=>['WHAT IS A SPARK?','KEYWORD LIBRARY'].includes(section.heading)))
const premadeSparkCards=computed(()=>sparks.map(([name,keywords])=>({name,keywords:keywords.split(',').map(value=>value.trim()).filter(Boolean),description:sparkDetails[name]?.description||''})).sort((a,b)=>a.name.localeCompare(b.name)))
const deedIntro=computed(()=>ruleSourceDocuments.deeds.sections.filter(section=>section.heading==='DEEDS'&&section.blocks.length).flatMap(section=>section.blocks.filter(block=>block.type==='paragraph').map(block=>block.type==='paragraph'?block.text:'')))
const deedEntries=computed<DeedEntry[]>(()=>deeds.map(deed=>({name:deed.name,flavor:deed.flavor,objective:deed.objective,reward:deedRewardLabel(deed),keywords:[...deed.keywords]})))
const deedEntriesSorted=computed(()=>{const sorted=[...deedEntries.value].sort((a,b)=>a.name.localeCompare(b.name));const n=sorted.length;return sorted.map((deed,index)=>{const start=Math.floor(index*100/n)+1,end=Math.floor((index+1)*100/n);const format=(value:number)=>String(value).padStart(2,'0');return{...deed,rollRange:`${format(start)}–${format(end)}`}})})
const sparkExamples=computed(()=>premadeSparkCards.value.filter(item=>['Courageous','Scholar'].includes(item.name)))
const creationSparkExample=computed(()=>premadeSparkCards.value.find(item=>item.name==='Healer')||premadeSparkCards.value[0])
const creationDeedExample=computed(()=>deedEntries.value.find(item=>item.name==='Gentle Guardian')||deedEntries.value[0])
function headingKey(value:string){return displayText(value).trim().toLowerCase().replace(/[’']/g,"'")}
function sectionByHeading(documentKey:string,heading:string){return ruleSourceDocuments[documentKey]?.sections.find(section=>headingKey(section.heading)===headingKey(heading))||null}
function commonSections(documentKey:string,names:readonly string[]){return names.map(name=>sectionByHeading(documentKey,name)).filter((section):section is RuleSourceSection=>Boolean(section))}
const commonHomelandSections=computed(()=>commonSections('homeland',homelands.map(item=>item.name)).sort((a,b)=>a.heading.localeCompare(b.heading)))
const commonOathSections=computed(()=>commonSections('oath',oaths.map(item=>item[0])).sort((a,b)=>a.heading.localeCompare(b.heading)))
const commonFaithSections=computed(()=>commonSections('faith',faiths).sort((a,b)=>a.heading.localeCompare(b.heading)))
const commonHeadingSets={homeland:new Set(homelands.map(item=>headingKey(item.name))),oath:new Set(oaths.map(item=>headingKey(item[0]))),faith:new Set(faiths.map(item=>headingKey(item)))}
function generalNarrativeSections(documentKey:string){if(documentKey!=='homeland'&&documentKey!=='oath'&&documentKey!=='faith')return[];const excluded=commonHeadingSets[documentKey];return (ruleSourceDocuments[documentKey]?.sections||[]).filter(section=>section.heading!=='Overview'&&!excluded.has(headingKey(section.heading)))}
function visibleNarrativeBlocks(section:RuleSourceSection){return section.blocks.filter(block=>!(block.type==='table'&&singleCellText(block).startsWith('WATCHER’S NOTE')))}
const faithWatcherNote=computed(()=>{for(const section of ruleSourceDocuments.faith.sections){for(const block of section.blocks){const text=singleCellText(block);if(text.startsWith('WATCHER’S NOTE'))return narrativeParts(text).body}}return''})
const oathWatcherNote='The Adventurer Oath serves as the default oath for characters who do not choose one or for tables that wish to omit the oath system entirely. It carries no virtue, strain or restrictions, and imposes no narrative expectations. Characters following the Adventurer Oath are guided solely by their own moral rhythm. Their Oath is personal interpretation — an open space for the player’s own moral compass. Use this Oath to represent self-reliant heroes, doubters, or free spirits who find meaning without divine or cultural guidance. When omens or blessings touch such a character, interpret them as echoes of the world itself — the rhythm of Brambleheart answering not promise, but intent.'
function narrativeIntroSections(documentKey:string){return generalNarrativeSections(documentKey).filter(section=>!/^CREATING A /i.test(section.heading))}
function narrativeCardDetail(documentKey:string,heading:string){return narrativeRuleDetail(documentKey,heading)}
function narrativeCardDescription(documentKey:string,heading:string){return sourceNarrativeDescription(documentKey,heading)}
const weaponQualitySections=computed(()=>ruleSourceDocuments.weapons.sections.map(section=>({...section,blocks:section.blocks.filter(block=>block.type==='table'&&block.rows.some(row=>row.some(cell=>/Quality/i.test(cell))))})).filter(section=>section.blocks.length))
const currentGearItems=computed(()=>catalogGearShopItems)
const shieldNames=new Set(['Sapguard','Sapguard*','Vinegrip','Ironwood Bulwark','IronwoodBulwark'])
function equipmentItemsFor(group:string){return currentGearItems.value.filter(item=>group==='Weapons'?item.category==='Weapon':group==='Armor'?item.category==='Armor & Shield'&&!shieldNames.has(item.name):group==='Shields'?item.category==='Armor & Shield'&&shieldNames.has(item.name):item.shopGroup===group).sort((a,b)=>a.name.localeCompare(b.name))}
const equipmentGroups=['Traveler’s Gear','Field Kits','Consumables','Trinkets','Tools'] as const
function weaponClass(item:typeof currentGearItems.value[number]){return /\bProjectile\s*\(/i.test(item.detail||'')?'Ranged Weapons':'Melee Weapons'}
const weaponTableGroups=computed(()=>['Melee Weapons','Ranged Weapons'].map(label=>({label,items:equipmentItemsFor('Weapons').filter(item=>weaponClass(item)===label).map(item=>({item,profile:weaponProfile(item)}))})))
function armorClass(item:typeof currentGearItems.value[number]){const might=Number((armorProfile(item).might.match(/\d+/)||['0'])[0]);return might>=4?'Heavy Armor':might>=2?'Medium Armor':'Light Armor'}
const armorTableGroups=computed(()=>['Light Armor','Medium Armor','Heavy Armor'].map(label=>({label,items:equipmentItemsFor('Armor').filter(item=>armorClass(item)===label).map(item=>({item,profile:armorProfile(item)}))})))
const shieldTableRows=computed(()=>equipmentItemsFor('Shields').map(item=>({item,profile:armorProfile(item)})))
function gearCardFields(item:typeof currentGearItems.value[number]){const fields:Array<{label:string;value:string}>=[];if(item.detail&&item.detail!=='—')fields.push({label:'PROFILE',value:item.detail});if(item.effect)fields.push({label:'EFFECT',value:item.effect});return fields}
function sectionParagraphs(section:RuleSourceSection|null){return section?.blocks.flatMap(block=>block.type==='paragraph'?[block.text]:[])||[]}
const equipmentOverviewSection=computed(()=>sectionByHeading('adventuring-gear','EQUIPMENT & GEAR'))
const makeshiftWeaponsSection=computed(()=>sectionByHeading('weapons','MAKESHIFT WEAPONS'))
const armorPenaltySection=computed(()=>sectionByHeading('armor-shields','ARMOR PENALTY'))
const breakValueSection=computed(()=>sectionByHeading('weapons','BREAK VALUE'))
const armorPenaltyText=computed(()=>sectionParagraphs(armorPenaltySection.value)[0]||'')
const breakValueText=computed(()=>sectionParagraphs(breakValueSection.value).join(' '))
const threadpieceSections=computed(()=>['THREADPIECES','Standard Exchange Rate'].map(heading=>sectionByHeading('adventuring-gear',heading)).filter((section):section is RuleSourceSection=>Boolean(section)))
const resaleSection=computed(()=>sectionByHeading('adventuring-gear','SELLING TREASURE & RESALE'))
const beyondIntroSection=computed(()=>sectionByHeading('beyond-creation','EXPERIENCE'))
const beyondSpendingSection=computed(()=>sectionByHeading('beyond-creation','SPENDING EXPERIENCE'))
const advancementTables=computed(()=>beyondSpendingSection.value?.blocks.filter((block):block is Extract<RuleSourceBlock,{type:'table'}>=>block.type==='table')||[])
const advancementSummaryTable=computed(()=>advancementTables.value[0]||null)
const advancementChartTables=computed(()=>advancementTables.value.slice(1))
const advancementChartTitles=['Attribute Rank','Skill Rank','Magic Level']
const xpMethodLabels=['Deeds Completed','Spark Alignment','Encounters','Awards & Milestones']
const xpMethodTones=['detail-tone-deed','detail-tone-spark','detail-tone-heritage','detail-tone-oath'] as const
const xpMethods=computed(()=>sectionParagraphs(beyondIntroSection.value).filter(text=>xpMethodLabels.some(label=>text.toLowerCase().startsWith(label.toLowerCase()+':'))).map(text=>labeledParagraph(text)))
const xpAverageLine=computed(()=>sectionParagraphs(beyondIntroSection.value).find(text=>/Average XP per session/i.test(text))||'')
function spellKeywordBody(text:string,title:string){return text.replace(new RegExp(`^${title.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}\\s*`, 'i'),'').trim()}
const magicPowerSection=computed(()=>sectionByHeading('winds-of-magic','MAGIC POWER'))
const manaPoolRule=computed(()=>sectionParagraphs(magicPowerSection.value).find(text=>/^MANA POOL:/i.test(text))?.replace(/^MANA POOL:\s*/i,'')||'')
const magicRegenRule=computed(()=>sectionParagraphs(magicPowerSection.value).find(text=>/^MAGIC REGEN:/i.test(text))?.replace(/^MAGIC REGEN:\s*/i,'')||'')
const castingSpellsSection=computed(()=>sectionByHeading('winds-of-magic','CASTING SPELLS'))
function castingRule(prefix:string){return sectionParagraphs(castingSpellsSection.value).find(text=>text.toUpperCase().startsWith(prefix.toUpperCase()))||''}
const spellToHitRule=computed(()=>castingRule('SPELL - TO HIT:').replace(/^SPELL - TO HIT:\s*/i,''))
const enhanceRule=computed(()=>castingRule('ENHANCE:').replace(/^ENHANCE:\s*/i,''))
const hexRule=computed(()=>castingRule('HEX:').replace(/^HEX:\s*/i,''))
const arcaneCommandAction=coreActions.find(action=>action.name==='ARCANE COMMAND')!
const endOfRoundText='Resolve effects that explicitly occur at the end of the round in Initiative Order. When those effects are complete, clear round-limited timing where required and begin the next Start of Round sequence.'
const threatLevelBands=THREAT_BANDS.map(band=>({level:band.level,score:threatBandScoreLabel(band),label:band.label}))
</script>

<template>
  <RulePageLayout
    v-if="page"
    :title="page.title"
    :section="breadcrumbSection"
    :summary="page.summary"
    :parent="layoutParent"
    back-to="/rules"
    back-label="Back to Rules"
    prefer-back-to
    skip-back-prefix="/rules/read/"
    :navigation="ruleNavigation"
  >

        <template v-if="currentCategoryLanding">
          <section class="rule-page-section chapter-landing-page">
            <h2>Contents</h2>
            <div class="chapter-landing-list"><RouterLink v-for="entry in landingEntries" :key="entry.slug" class="chapter-landing-link" :to="`/rules/read/${entry.slug}`"><span><strong>{{ entry.title }}</strong><small>{{ entry.summary }}</small></span><span aria-hidden="true">›</span></RouterLink></div>
          </section>
        </template>

        <template v-else-if="page.slug==='playable-species'">
          <section class="rule-page-section playable-species-reader">
            <h2>Woodlands</h2>
            <p>Choose a Species to open its current lore, Heritage Traits, Cultural Traits, and language.</p>
            <div class="playable-species-link-list"><RouterLink v-for="species in speciesData" :key="species.name" class="list-row" :to="`/rules/read/species-${species.name.toLowerCase()}`"><span class="list-row-copy"><span class="list-row-title">{{ species.name }}</span></span><svg class="row-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></RouterLink></div>
          </section>
        </template>

        <template v-else-if="currentSpecies">
          <SpeciesRuleSheet :species="currentSpecies" />
        </template>

        <template v-else-if="page.slug==='talents'">
          <section class="rule-page-section-stack talent-rule-page">
            <section class="rule-page-section talent-rules-intro"><h2>Talents</h2><p v-for="line in sectionParagraphs(sectionByHeading('talents','TALENTS'))" :key="line">{{ displayText(line) }}</p><p>Talent categories group related techniques by how they interact with Core Actions, Abilities, magic, movement, and other character rules. Open a category to review its current Talents.</p></section>
            <details v-for="group in talentRuleGroups" :key="group.category" class="organized-rule-category talent-category-panel card-surface">
              <summary><h2>{{ group.category }}</h2></summary>
              <div class="organized-rule-category-body review-box-list">
                <article v-for="talent in group.talents" :key="talent" class="talent-detail-card full-rule-entry" :class="abilityTypes(talentRuleKeywords(talent)).map(abilityTypeClass)">
                  <div class="talent-detail-head"><div><h2>{{ talent }}</h2></div><div class="talent-head-actions"><span v-if="manaCostFromRule(talentRuleText(talent))!==null" class="mana-badge">{{ manaCostFromRule(talentRuleText(talent)) }} Mana</span></div></div>
                  <p v-if="structuredRule(talentRuleText(talent)).intro" class="rule-flavor"><em>{{ structuredRule(talentRuleText(talent)).intro }}</em></p>
                  <div v-if="visibleRuleFields(talentRuleText(talent)).length" class="rule-breakdown-grid"><div v-for="field in visibleRuleFields(talentRuleText(talent))" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div>
                  <div class="keyword-pill-row"><span v-for="keyword in abilityFeaturePillKeywords(talentRuleKeywords(talent))" :key="keyword" :class="abilityFeaturePillClass(keyword)">{{ abilityFeaturePillLabel(keyword) }}</span></div>
                </article>
              </div>
            </details>
          </section>
