            <h2>{{ currentSpellLore==='Invocation'?'Invocation Spells':`Lore of ${currentSpellLore}` }}</h2>
            <div class="lore-reader-meta">
              <strong v-if="currentLoreResistance" class="lore-elemental-resistance">Elemental Resistance: {{ currentLoreResistance }}</strong>
              <label v-if="canPreviewLoreAttunement" class="lore-attunement-preview-toggle"><span>Attuned</span><span class="switch"><input v-model="loreAttunedPreview" type="checkbox" /><span></span></span></label>
              <small>{{ currentLoreSpells.length }} spells</small>
            </div>
            <p v-if="loreDescriptions[currentSpellLore]" class="lore-reader-description">{{ loreDescriptions[currentSpellLore] }}</p>
            <div class="review-spell-column">
              <article v-for="spell in currentLoreSpells.filter(isSignatureSpell)" :key="spell" class="spell-detail-card full-rule-entry" :class="spellLoreClass(spell)"><div class="spell-detail-head"><div><h2>{{ spell }}</h2></div><span class="mana-badge">{{ displayedLoreCost(spell) }}</span></div><p v-if="spellRuleDetail(spell)?.flavor" class="rule-flavor"><em>{{ spellRuleDetail(spell)?.flavor }}</em></p><div v-if="visibleRuleFields(spellRuleDetail(spell)?.rules||'').length" class="rule-breakdown-grid"><div v-for="field in visibleRuleFields(spellRuleDetail(spell)?.rules||'')" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div><div v-if="spellRuleDetail(spell)?.keywords?.length" class="keyword-pill-row"><span v-for="keyword in abilityFeaturePillKeywords(spellRuleDetail(spell)?.keywords)" :key="keyword" :class="abilityFeaturePillClass(keyword)">{{ abilityFeaturePillLabel(keyword) }}</span></div></article>
              <details v-for="spell in currentLoreSpells.filter(spell=>!isSignatureSpell(spell))" :key="spell" class="organized-rule-category spell-collapsible card-surface" :class="spellLoreClass(spell)"><summary><span><h2>{{ spell }}</h2><small>{{ displayedLoreCost(spell) }}</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body"><p v-if="spellRuleDetail(spell)?.flavor" class="rule-flavor"><em>{{ spellRuleDetail(spell)?.flavor }}</em></p><div v-if="visibleRuleFields(spellRuleDetail(spell)?.rules||'').length" class="rule-breakdown-grid"><div v-for="field in visibleRuleFields(spellRuleDetail(spell)?.rules||'')" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div><div v-if="spellRuleDetail(spell)?.keywords?.length" class="keyword-pill-row"><span v-for="keyword in abilityFeaturePillKeywords(spellRuleDetail(spell)?.keywords)" :key="keyword" :class="abilityFeaturePillClass(keyword)">{{ abilityFeaturePillLabel(keyword) }}</span></div></div></details>
            </div>
          </section>
        </template>

        <template v-else-if="page.slug==='magical-levels'">
          <section class="rule-page-section-stack magical-levels-page">
            <section v-if="magicPowerSection" class="rule-page-section"><h2>Magic Power</h2><p v-for="line in sectionParagraphs(magicPowerSection).filter(line=>!/^MANA POOL:|^MAGIC REGEN:/i.test(line))" :key="line">{{ displayText(line) }}</p><div class="magic-resource-grid"><RuleFeatureCard title="Mana Pool" subtitle="MAXIMUM MANA" tone-class="type-magic"><p>{{ displayText(manaPoolRule) }}</p></RuleFeatureCard><RuleFeatureCard title="Magic Regen" subtitle="START OF ROUND" tone-class="type-instinct"><p>{{ displayText(magicRegenRule) }}</p></RuleFeatureCard></div></section>
            <section v-if="sectionByHeading('winds-of-magic','KNOWN SPELLS')" class="rule-page-section"><h2>Known Spells</h2><template v-for="(block,index) in sectionByHeading('winds-of-magic','KNOWN SPELLS')!.blocks" :key="index"><p v-if="block.type==='paragraph'">{{ displayText(block.text) }}</p><div v-else class="rule-table-wrap known-spells-table"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div></template></section>
            <section v-if="sectionByHeading('winds-of-magic','LORE ATTUNEMENT')" class="rule-page-section"><h2>Lore Attunement</h2><p v-for="line in sectionParagraphs(sectionByHeading('winds-of-magic','LORE ATTUNEMENT'))" :key="line">{{ displayText(line) }}</p><aside class="rule-narrative-note signature-rule-panel"><strong>SIGNATURE</strong><p v-for="line in sectionParagraphs(sectionByHeading('winds-of-magic','SIGNATURE'))" :key="line">{{ displayText(line) }}</p></aside><article v-if="signatureExample" class="spell-detail-card full-rule-entry spell-lore-flames signature-example-card"><div class="spell-detail-head"><div><h3>{{ signatureExampleName }}</h3></div><span class="mana-badge">SIGNATURE</span></div><p v-if="signatureExample.flavor" class="rule-flavor"><em>{{ signatureExample.flavor }}</em></p><div class="rule-breakdown-grid"><div v-for="field in visibleRuleFields(signatureExample.rules)" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div></article></section>
          </section>
        </template>

        <template v-else-if="page.slug==='spell-types-targeting'">
          <section class="rule-page-section-stack spell-targeting-page">
            <section class="rule-page-section"><h2>Spell Keywords</h2><p v-if="spellMagicKeywordText" class="spell-magic-keyword-text">{{ displayText(spellMagicKeywordText) }}</p><div class="spell-keyword-card-grid"><RuleFeatureCard v-for="item in spellKeywordCards" :key="item.title" :title="item.title" subtitle="SPELL KEYWORD" tone-class="type-magic"><p>{{ spellKeywordBody(item.text,item.title) }}</p><template #footer><div class="keyword-pill-row"><span class="ability-cost-pill type-magic">{{ item.title }}</span></div></template></RuleFeatureCard></div></section>
            <section class="rule-page-section"><h2>Casting Spells</h2><RuleFeatureCard title="Spell - To Hit" subtitle="MAGIC STRIKE" tone-class="type-magic"><p>{{ displayText(spellToHitRule) }}</p></RuleFeatureCard><div class="spell-resolution-pair"><RuleFeatureCard title="Enhance" subtitle="BENEFICIAL SPELL" tone-class="detail-tone-heritage" :fields="structuredRule(enhanceRule).fields"><p v-if="structuredRule(enhanceRule).intro">{{ structuredRule(enhanceRule).intro }}</p><template #footer><div class="keyword-pill-row"><span class="ability-cost-pill type-magic">ENHANCE</span></div></template></RuleFeatureCard><RuleFeatureCard title="Hex" subtitle="HOSTILE SPELL" tone-class="detail-tone-deed" :fields="structuredRule(hexRule).fields"><p v-if="structuredRule(hexRule).intro">{{ structuredRule(hexRule).intro }}</p><template #footer><div class="keyword-pill-row"><span class="ability-cost-pill type-magic">HEX</span></div></template></RuleFeatureCard></div><p v-for="line in sectionParagraphs(castingSpellsSection).filter(line=>!/^SPELL - TO HIT:|^ENHANCE:|^HEX:/i.test(line))" :key="line">{{ displayText(line) }}</p><div class="core-magic-reference-grid"><CoreActionCard :action="arcaneCommandAction" /><CoreActionCard :action="renewTheHeartAction" /></div></section>
            <section class="rule-page-section"><h2>Summon</h2><p v-for="line in sectionParagraphs(sectionByHeading('winds-of-magic','SUMMON'))" :key="line">{{ displayText(line) }}</p></section>
            <section class="rule-page-section"><h2>Spell Range</h2><p v-for="line in sectionParagraphs(sectionByHeading('winds-of-magic','SPELL RANGE'))" :key="line">{{ displayText(line) }}</p><div class="spell-range-example-graphic" role="img" aria-label="Spell range example showing square-by-square distance to a point of origin with a three by three area centered on the endpoint."><div class="spell-range-example-heading"><strong>Hallowing Thorns</strong><span>Range [5] · ORB[3]</span></div><div class="spell-range-square-demo"><span class="range-grid-square caster-square">Caster</span><span v-for="step in 4" :key="step" class="range-grid-square"><small>{{ step }}</small></span><span class="range-origin-wrap"><span class="range-area-grid" aria-label="3 by 3 area"><i v-for="cell in 9" :key="cell" :class="{origin:cell===5}"></i></span><span class="range-grid-square origin-square">Point</span></span></div><small class="spell-range-square-note">Count squares from the caster to the chosen point. The area then covers the 3 × 3 squares centered on that endpoint.</small></div><details class="organized-rule-category targeting-shapes-menu card-surface"><summary><span><h3>Area-Of-Effect Radius</h3></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body"><section v-for="rule in targetingRules" :key="rule.title" class="targeting-rule-card"><h3>{{ rule.title }}</h3><div class="targeting-rule-layout"><div><p>{{ rule.text }}</p><p class="rule-example-copy"><strong>Example:</strong> {{ rule.example }}</p><div class="keyword-pill-row targeting-bottom-pills"><span class="keyword-pill">{{ rule.keyword }}</span></div></div><img :src="rule.image" :alt="`${rule.title} Spell targeting diagram`" /></div></section><section class="targeting-rule-card"><h3>Impassable Collision</h3><div class="targeting-rule-layout compact"><div><p>Impassable terrain stops an Ability’s area unless that Ability explicitly says it can pass through the obstacle. Squares behind the blocking terrain are not affected even when they would otherwise fall inside the shape.</p></div><img :src="targetingBlockedImage" alt="Cone area blocked by impassable terrain" /></div></section></div></details><p class="weapon-range-link-copy">Weapon attacks use their printed weapon range, Reach, Thrown, line of sight, and Range Strike rules. Open Attacking &amp; Defending for weapon attack range and opposed Strike resolution.</p><div class="rule-link-buttons centered-rule-links"><RouterLink class="secondary-button" to="/rules/read/attacking-defending">Attacking &amp; Defending</RouterLink></div></section>
          </section>
        </template>

        <template v-else-if="page.slug==='attacking-defending'">
          <section class="organized-rule-stack attack-defense-page">
            <section class="rule-page-section strike-intro-card"><h2>To Hit &amp; To Ward</h2><p>When an attack calls for an opposed Strike, the attacker builds the roll from the Stat named by the action and the defender answers with Ward. Melee Strike uses Brawl, Range Strike uses Aim, and a Magic Strike uses Control. The defender rolls Ward, which is the Hide modifier.</p><p>Roll both sides, apply Conditions and other modifiers, then compare the totals. The attack succeeds only when the attacker finishes higher. A Ward total that equals or exceeds the attack total successfully defends.</p><div class="attack-defense-graphic" role="img" aria-label="Attack total is compared against Ward total. The higher total wins and the defender wins ties."><div class="attack-node"><small>ATTACKER</small><strong>3d10 + Brawl, Aim, or Control</strong><span>+ condition(s)</span></div><b>VS</b><div class="defense-node"><small>DEFENDER</small><strong>3d10 + Ward</strong><span>+ condition(s)</span></div><div class="resolution-node"><small>RESOLUTION</small><strong>Higher attack total hits</strong><span>Ward that ties or beats the attack defends.</span></div></div><RuleFeatureCard title="Tie Goes to the Defender" subtitle="RESOLUTION" tone-class="detail-tone-spark"><p>An attacker finishes with a total of <strong>21</strong>. The defender’s Ward roll also totals <strong>21</strong>. The defender successfully defends because Ward wins the tie.</p></RuleFeatureCard></section>
            <section class="core-attack-reference rule-page-section"><h2>Core Attack Actions</h2><p>These three shared Core Combat Actions use the same canonical cards as the Core Actions rules.</p><div class="core-attack-grid core-attack-list"><CoreActionCard v-for="action in combatAttackCoreActions" :key="action.name" :action="action" /></div></section>
            <section class="rule-page-section combat-range-section"><h2>Combat Range</h2><div class="combat-range-grid"><RuleFeatureCard title="Touch" subtitle="MELEE / CLOSE RANGE" tone-class="type-touch"><p>Any weapon or Ability that does not state a distance is considered Touch. Use its printed reach when one is stated; otherwise Touch reaches a target within [1] square.</p><template #footer><div class="keyword-pill-row"><span class="ability-cost-pill type-touch">TOUCH</span></div></template></RuleFeatureCard><RuleFeatureCard title="Projectile &amp; Thrown" subtitle="WEAPON TARGETING" tone-class="type-shoot"><p>A Projectile or Thrown weapon targets a character within its printed distance and line of sight. Use the weapon’s listed Projectile or Thrown distance and all restrictions printed by the action or weapon quality.</p><template #footer><div class="keyword-pill-row"><span class="ability-cost-pill type-shoot">PROJECTILE</span><span class="keyword-pill">THROWN</span></div></template></RuleFeatureCard></div><div class="rule-link-buttons centered-rule-links"><RouterLink class="secondary-button" to="/rules/read/spell-types-targeting">Area-of-Effect Targeting Rules</RouterLink></div></section>
          </section>
        </template>

        <template v-else-if="page.slug==='encounter-rounds'">
          <section class="encounter-rounds-page organized-rule-stack">
            <section v-if="combatEncounterSection" class="rule-page-section encounter-rule-section"><h2>Encounters</h2><p v-for="line in sectionParagraphs(combatEncounterSection)" :key="line">{{ displayText(line) }}</p><div class="encounter-round-flow" role="img" aria-label="Encounter flow from positions through repeating rounds."><span><small>1</small><strong>Set Positions</strong></span><b>→</b><span><small>2</small><strong>Roll Initiative</strong></span><b>→</b><span><small>3</small><strong>Start of Round</strong></span><b>→</b><span><small>4</small><strong>Turns in Order</strong></span><b>→</b><span><small>5</small><strong>End of Round</strong></span></div></section>
            <section v-if="determiningPositionsSection" class="rule-page-section encounter-rule-section"><h2>Determining Positions</h2><p v-for="line in sectionParagraphs(determiningPositionsSection)" :key="line">{{ displayText(line) }}</p><aside v-if="squaresMeasurementsSection" class="rule-narrative-note watcher-note-panel measurement-note-panel"><strong>SQUARES &amp; MEASUREMENTS</strong><p v-for="line in sectionParagraphs(squaresMeasurementsSection)" :key="line">{{ displayText(line) }}</p></aside><div class="square-measurement-graphic" role="img" aria-label="One combat square is approximately one yard, three feet, or one meter."><span><small>GRID</small><strong>1 Square</strong></span><b>=</b><span><small>TABLETOP DISTANCE</small><strong>1 Yard</strong></span><b>≈</b><span><strong>3 Feet</strong></span><b>≈</b><span><strong>1 Meter</strong></span></div></section>
            <section v-if="initiativeSection" class="rule-page-section encounter-rule-section"><h2>Initiative Order</h2><p v-for="line in sectionParagraphs(initiativeSection)" :key="line">{{ displayText(line) }}</p><div class="initiative-roll-graphic initiative-accent-graphic"><span><small>ROLL</small><strong>3d10 + Speed + condition(s)</strong></span><b>→</b><span><small>ORDER</small><strong>Highest result acts first</strong></span></div><div class="initiative-order-example initiative-accent-graphic"><strong>Example Initiative</strong><ol><li><b>Selu</b><span>27</span></li><li><b>Blight Warrior</b><span>23</span></li><li><b>Nessa</b><span>19</span></li><li class="watcher-position"><b>Watcher Event</b><span>16</span></li><li><b>Brann</b><span>13</span></li></ol></div></section>
            <section v-if="roundsTurnsSection" class="rule-page-section encounter-rule-section"><h2>Rounds &amp; Turns</h2><p v-for="line in sectionParagraphs(roundsTurnsSection)" :key="line"><template v-if="/^START OF ROUND:/i.test(line)"><strong>START OF ROUND:</strong> {{ displayText(line).replace(/^START OF ROUND:\s*/i,'') }}</template><template v-else>{{ displayText(line) }}</template></p><section v-if="manaSection" class="mana-resource-reference"><h3>Mana</h3><div class="magic-resource-grid"><RuleFeatureCard title="Mana Pool" subtitle="MAXIMUM MANA" tone-class="type-magic"><p><strong>Magic Level + Spirit</strong></p></RuleFeatureCard><RuleFeatureCard title="Magic Regen" subtitle="START OF ROUND" tone-class="type-instinct"><p><strong>Heart + Condition</strong></p></RuleFeatureCard></div><p>{{ displayText(sectionParagraphs(manaSection)[2]||'') }}</p></section><p>Before Magic Regen is restored, each character may resolve one eligible <strong>Instinct Core Action</strong> during Start of Round.</p><div class="core-action-grid instinct-action-grid"><CoreActionCard v-for="action in instinctCoreActions" :key="action.name" :action="action" /></div></section>
            <section v-if="takingTurnSection" class="rule-page-section encounter-rule-section"><h2>Taking Your Turn</h2><p>{{ displayText(sectionParagraphs(takingTurnSection)[0]||'') }}</p><div class="turn-action-opportunity-grid"><article class="turn-opportunity type-move"><small>DYNAMIC</small><strong>CORE · MOVE</strong><span class="ability-cost-pill type-move">MOVE</span></article><article class="turn-opportunity type-combat"><small>ON A TURN</small><strong>CORE · COMBAT</strong><span class="ability-cost-pill type-combat">COMBAT</span></article></div><p v-for="line in sectionParagraphs(takingTurnSection).slice(1)" :key="line">{{ displayText(line) }}</p><div class="rule-link-buttons centered-rule-links"><RouterLink class="secondary-button" to="/rules/read/abilities">Core Actions</RouterLink><RouterLink class="secondary-button" to="/rules/read/attacking-defending">Attacking &amp; Defending</RouterLink></div></section>
            <section class="rule-page-section encounter-rule-section"><h2>End of Round</h2><p><strong>END OF ROUND:</strong> {{ endOfRoundText }}</p><p>Species Traits with an end-of-round Instinct Trigger can resolve here when their requirements are met.</p><div class="instinct-trait-example-grid"><article v-for="item in instinctTraitExamples" :key="`${item.species}-${item.trait.name}`" class="trait-card species-trait-rule" :class="item.kind==='Heritage'?'heritage-trait-card':'culture-trait-card'"><div class="trait-card-head"><div><h3>{{ item.trait.name }}</h3><small>{{ item.species }} · {{ item.kind }}</small></div></div><p v-if="structuredRule(item.trait.text).intro" class="rule-flavor">{{ structuredRule(item.trait.text).intro }}</p><div v-if="visibleRuleFields(item.trait.text).length" class="rule-breakdown-grid"><div v-for="field in visibleRuleFields(item.trait.text)" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div><div class="keyword-pill-row"><span v-for="keyword in abilityFeaturePillKeywords(item.trait.keywords)" :key="keyword" :class="abilityFeaturePillClass(keyword)">{{ abilityFeaturePillLabel(keyword) }}</span></div></article></div></section>
          </section>
        </template>

        <template v-else-if="page.slug==='encounters-threat-level'">
          <section class="external-rule-page rule-page-section-stack threat-level-page">
            <section class="rule-page-section"><h2>Threat Level</h2><p>Threat Level is a character-power gauge built from advancement beyond the ordinary starting baseline. Species, Spark, Homeland, Faith, Oath, and ordinary starting equipment do not add Threat on their own.</p><div class="threat-score-grid"><RuleFeatureCard title="Attribute Growth" subtitle="THREAT SCORE" tone-class="detail-tone-heritage"><p>Gain <strong>+2</strong> Threat Score for each Attribute rank above Rank 2.</p></RuleFeatureCard><RuleFeatureCard title="Skill Growth" subtitle="THREAT SCORE" tone-class="detail-tone-spark"><p>Gain <strong>+1</strong> Threat Score for each Skill rank above Rank 2.</p></RuleFeatureCard><RuleFeatureCard title="Talents" subtitle="THREAT SCORE" tone-class="detail-tone-talent"><p>The first Talent contributes <strong>+3</strong> Threat Score. Each additional Talent contributes <strong>+1</strong>.</p></RuleFeatureCard><RuleFeatureCard title="Magic Level" subtitle="THREAT SCORE" tone-class="detail-tone-magic"><p>The first Magic Level contributes <strong>+3</strong> Threat Score. Each additional Magic Level contributes <strong>+2</strong>.</p></RuleFeatureCard><RuleFeatureCard title="Exceptional Gear" subtitle="WATCHER ADJUSTMENT" tone-class="detail-tone-equipment"><p>At the Watcher’s discretion, exceptional, rare, or custom gear may add <strong>+1 to +5</strong> Threat Score based on how much it increases the character’s power beyond ordinary equipment.</p></RuleFeatureCard></div></section>
            <section class="rule-page-section"><h2>Individual Threat</h2><p>Add the character’s Threat Score and compare it to the chart. The character sheet calculates the automatic portion from Attributes, Skills, Talents, and Magic Level; a Watcher may add the Exceptional Gear adjustment when appropriate.</p><div class="rule-table-wrap"><table class="rule-source-table threat-level-table"><thead><tr><th>Threat Level</th><th>Threat Score</th><th>Power Band</th></tr></thead><tbody><tr v-for="band in threatLevelBands" :key="band.level"><td>TL {{ band.level }}</td><td>{{ band.score }}</td><td>{{ band.label }}</td></tr></tbody></table></div><div class="group-threat-example secondary"><span><small>WORKED HERO</small><strong>Attributes 8 + Skills 2 + Talents 5 + Magic 5 + Gear 2</strong></span><b>=</b><span><small>THREAT SCORE</small><strong>22 · TL 3</strong></span></div></section>
            <section class="rule-page-section"><h2>Group Threat</h2><p>For a party, add the Threat Levels of every player character to create the party’s <strong>Group Threat</strong>. Add the raw Threat Scores as a second comparison when two groups have the same Group Threat but different amounts of advancement inside their current bands.</p><div class="group-threat-example"><span><small>HEROES</small><strong>TL 1 + TL 2 + TL 2 + TL 3</strong></span><b>=</b><span><small>GROUP THREAT</small><strong>8</strong></span></div><div class="group-threat-example secondary"><span><small>RAW THREAT SCORES</small><strong>7 + 12 + 18 + 22</strong></span><b>=</b><span><small>GROUP SCORE</small><strong>59</strong></span></div></section>
          </section>
        </template>

        <template v-else-if="page.slug==='monsters' || page.slug==='critters'">
          <section class="monster-index-stack rule-page-section-stack"><section class="rule-page-section monster-source-intro"><h2>{{ page.slug==='critters'?'Critters & Companions':'Monsters of Anthro Mundas' }}</h2><p>The creature reference is organized first by parent category and then, for monsters with variants, by their monster type.</p></section><template v-for="group in monsterGroups" :key="group.category.name"><section v-if="group.monsters.length && (page.slug==='monsters'?group.category.name!=='Companions':group.category.name==='Companions')" class="rule-page-section monster-category-section"><h2>{{ group.category.name }}</h2><p>{{ group.category.summary }}</p><div class="monster-family-stack"><template v-for="family in group.families" :key="family.parent.name"><details v-if="family.children.length" class="monster-family-box"><summary><span><strong>{{ family.parent.name }}</strong><small>{{ family.children.length }} {{ family.children.length===1?'variant':'variants' }}</small></span><span aria-hidden="true">⌄</span></summary><div class="monster-link-grid"><RouterLink :to="`/rules/read/${monsterSlug(family.parent.name)}`"><strong>{{ family.parent.name }}</strong></RouterLink><RouterLink v-for="monster in family.children" :key="monster.name" :to="`/rules/read/${monsterSlug(monster.name)}`"><strong>{{ monster.name }}</strong></RouterLink></div></details><RouterLink v-else class="monster-family-link" :to="`/rules/read/${monsterSlug(family.parent.name)}`"><strong>{{ family.parent.name }}</strong></RouterLink></template></div></section></template></section>
        </template>

        <template v-else-if="currentMonster">
          <section class="external-monster-page"><section class="rule-page-section monster-profile-section"><h2>{{ currentMonster.name }}</h2><p class="rule-section-count">{{ currentMonster.category }}<template v-if="currentMonster.group"> · {{ currentMonster.group }}</template></p><p>{{ currentMonster.summary }}</p><p class="source-status-note">{{ currentMonster.placeholder?'Placeholder creature name reserved for future Watcher design. No Brambleheart stat block is assigned yet.':'This creature is established in the Watcher catalog, but a complete Brambleheart stat block has not yet been defined. Missing statistics are not invented.' }}</p></section></section>
        </template>

        <template v-else-if="page.slug==='sparks-deeds'">
          <section class="deeds-rule-page organized-rule-stack">
            <section class="rule-page-section spark-rule-card"><h2>What is a Spark?</h2><template v-for="section in sparkWhatSections" :key="section.heading"><template v-for="(block,index) in section.blocks" :key="`${section.heading}-${index}`"><p v-if="block.type==='paragraph'&&(!/^Keywords:/i.test(block.text)||section.heading==='KEYWORD LIBRARY')"><strong v-if="/^Deed Interaction:/i.test(block.text)" class="rule-inline-label">Deed Interaction:</strong><strong v-else-if="/^Keywords:/i.test(block.text)" class="rule-inline-label">Keywords:</strong>{{ displayText(block.text).replace(/^Deed Interaction:\s*/i,'').replace(/^Keywords:\s*/i,'') }}</p></template></template><div class="creation-reference-graphic creation-example-pair spark-rule-examples"><RuleFeatureCard v-for="spark in sparkExamples" :key="spark.name" :title="spark.name" subtitle="SPARK" tone-class="detail-tone-spark"><p>{{ spark.description }}</p><template #footer><div class="keyword-pill-row"><span v-for="keyword in spark.keywords" :key="keyword" class="keyword-pill">{{ keyword }}</span></div></template></RuleFeatureCard></div></section>
            <details class="organized-rule-category card-surface premade-sparks-menu"><summary><h2>Sparks - List</h2></summary><div class="organized-rule-category-body narrative-card-grid premade-spark-grid"><RuleFeatureCard v-for="spark in premadeSparkCards" :key="spark.name" :title="spark.name" subtitle="SPARK" tone-class="detail-tone-spark"><p v-if="spark.description">{{ spark.description }}</p><template #footer><div class="keyword-pill-row"><span v-for="keyword in spark.keywords" :key="keyword" class="keyword-pill">{{ keyword }}</span></div></template></RuleFeatureCard></div></details>
            <section class="rule-page-section deed-intro-box"><h2>Deeds</h2><div class="deed-structure-copy"><p v-for="line in deedIntro.filter(line=>!/^RANDOM GENERATION:/i.test(line))" :key="line"><strong v-if="labeledParagraph(line).label" class="rule-inline-label">{{ labeledParagraph(line).label }}:</strong>{{ labeledParagraph(line).body }}</p><aside class="rule-narrative-note percentile-generation-panel"><strong>RANDOM GENERATION</strong><p>{{ displayText(deedIntro.find(line=>/^RANDOM GENERATION:/i.test(line))||'').replace(/^RANDOM GENERATION:\s*/i,'') }}</p><div class="percentile-roll-graphic" role="img" aria-label="Percentile dice example: a tens die showing 4 and a ones die showing 7 produce 47."><span><small>TENS DIE</small><strong>4</strong></span><span><small>ONES DIE</small><strong>7</strong></span><b>=</b><span class="percentile-result"><small>RESULT</small><strong>47</strong></span></div><small>Choose which d10 is tens and which is ones before rolling. 00 counts as 100.</small></aside></div></section>
            <details class="organized-rule-category card-surface deed-cards-menu"><summary><h2>Deed - List</h2></summary><div class="organized-rule-category-body deed-rule-list"><RuleFeatureCard v-for="deed in deedEntriesSorted" :key="deed.name" :title="deed.name" subtitle="DEED" :badge="deed.reward" tone-class="detail-tone-deed" :fields="[{label:'OBJECTIVE',value:deed.objective}]"><p v-if="deed.flavor">{{ deed.flavor }}</p><template #footer><div class="deed-card-footer"><div class="keyword-pill-row"><span v-for="keyword in deed.keywords" :key="keyword" class="keyword-pill">{{ keyword }}</span></div><span class="deed-roll-result" :aria-label="`percentile result ${deed.rollRange}`">{{ deed.rollRange }}</span></div></template></RuleFeatureCard></div></details>
          </section>
        </template>

        <template v-else-if="page.slug==='homeland'||page.slug==='oath'||page.slug==='faith'">
          <section class="rule-page-section-stack narrative-rule-page">
            <section v-for="section in narrativeIntroSections(page.slug)" :key="section.heading" class="rule-page-section"><h2>{{ displayText(section.heading) }}</h2><template v-for="(block,index) in visibleNarrativeBlocks(section)" :key="index"><p v-if="block.type==='paragraph'">{{ displayText(block.text) }}</p><div v-else class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div></template></section>
            <details class="organized-rule-category card-surface common-narrative-section"><summary><h2>{{ page.slug==='homeland'?'Homeland - List':page.slug==='oath'?'Oath - List':'Faith - List' }}</h2></summary><div class="organized-rule-category-body narrative-card-grid" :class="{'two-column-oaths':page.slug==='oath'}"><article v-for="section in (page.slug==='homeland'?commonHomelandSections:page.slug==='oath'?commonOathSections:commonFaithSections)" :key="section.heading" class="choice-summary" :class="page.slug==='homeland'?'homeland-description-card detail-tone-homeland':'faith-oath-detail-card '+`detail-tone-${page.slug}`"><template v-if="page.slug==='homeland'"><h2>{{ displayText(section.heading) }}</h2><p>{{ homelandDetails[section.heading]?.description||narrativeCardDescription('homeland',section.heading) }}</p><div class="homeland-skill-copy"><strong>Skills</strong><div class="keyword-pill-row"><span v-for="skill in homelandDetails[section.heading]?.skills||[]" :key="skill" class="keyword-pill">{{ skill }}</span></div><small v-if="homelandDetails[section.heading]?.optionalReplacements?.length"><strong>Optional</strong></small><div v-if="homelandDetails[section.heading]?.optionalReplacements?.length" class="keyword-pill-row"><span v-for="skill in homelandDetails[section.heading]?.optionalReplacements||[]" :key="skill" class="keyword-pill alternate-pill">{{ skill }}</span></div></div></template><template v-else><header><h2>{{ displayText(section.heading) }}</h2><small>{{ page.slug.toUpperCase() }}</small></header><p v-if="narrativeCardDetail(page.slug,section.heading).intro||narrativeCardDescription(page.slug,section.heading)">{{ narrativeCardDetail(page.slug,section.heading).intro||narrativeCardDescription(page.slug,section.heading) }}</p><div class="narrative-detail-grid"><div v-if="narrativeCardDetail(page.slug,section.heading).voice"><small>VOICE</small><span>{{ narrativeCardDetail(page.slug,section.heading).voice }}</span></div><div v-if="narrativeCardDetail(page.slug,section.heading).virtue"><small>VIRTUE</small><span>{{ narrativeCardDetail(page.slug,section.heading).virtue }}</span></div><div v-if="narrativeCardDetail(page.slug,section.heading).strain"><small>STRAIN</small><span>{{ narrativeCardDetail(page.slug,section.heading).strain }}</span></div><div v-if="narrativeCardDetail(page.slug,section.heading).creed"><small>CREED</small><span>{{ narrativeCardDetail(page.slug,section.heading).creed }}</span></div><div v-if="narrativeCardDetail(page.slug,section.heading).practices.length"><small>PRACTICES</small><ul><li v-for="item in narrativeCardDetail(page.slug,section.heading).practices" :key="item">{{ item }}</li></ul></div><div v-if="narrativeCardDetail(page.slug,section.heading).taboos.length"><small>TABOOS</small><ul><li v-for="item in narrativeCardDetail(page.slug,section.heading).taboos" :key="item">{{ item }}</li></ul></div><div v-if="narrativeCardDetail(page.slug,section.heading).signs"><small>SIGNS</small><span>{{ narrativeCardDetail(page.slug,section.heading).signs }}</span></div><div v-if="narrativeCardDetail(page.slug,section.heading).conflictHook"><small>CONFLICT HOOK</small><span>{{ narrativeCardDetail(page.slug,section.heading).conflictHook }}</span></div></div></template></article></div></details>
            <aside v-if="page.slug==='faith'&&faithWatcherNote" class="rule-narrative-note watcher-note-panel"><strong>WATCHER’S NOTE</strong><p>{{ faithWatcherNote }}</p></aside>
            <aside v-if="page.slug==='oath'" class="rule-narrative-note watcher-note-panel"><strong>WATCHER’S NOTE</strong><p>{{ oathWatcherNote }}</p></aside>
          </section>
        </template>

        <template v-else-if="page.slug==='adventuring-gear'">
          <section class="rule-page-section-stack equipment-rules-organized">
            <section class="rule-page-section equipment-overview-section"><h2>Equipment &amp; Gear</h2><p v-for="line in sectionParagraphs(equipmentOverviewSection)" :key="line">{{ displayText(line) }}</p></section>
            <section class="rule-page-section equipment-rule-section"><h2>Weapons</h2><div class="rule-table-wrap equipment-profile-table"><table class="rule-source-table equipment-stat-table"><thead><tr><th>Weapon</th><th>Damage</th><th>Range</th><th>Weight</th><th>Qualities</th><th>Cost</th></tr></thead><tbody><template v-for="group in weaponTableGroups" :key="group.label"><tr class="equipment-group-row"><th colspan="6">{{ group.label }}</th></tr><tr v-for="row in group.items" :key="row.item.name"><td>{{ row.item.name }}</td><td>{{ row.profile.damage }}</td><td>{{ row.profile.range }}</td><td>{{ row.profile.weight }}</td><td>{{ row.profile.properties }}</td><td>{{ row.item.costText }}</td></tr></template></tbody></table></div><aside v-if="makeshiftWeaponsSection" class="rule-narrative-note watcher-note-panel equipment-rule-note"><strong>MAKESHIFT WEAPONS</strong><p v-for="line in sectionParagraphs(makeshiftWeaponsSection)" :key="line">{{ displayText(line) }}</p></aside></section>
            <section class="rule-page-section equipment-rule-section"><h2>Weapon Qualities</h2><div class="equipment-source-stack"><section v-for="section in weaponQualitySections" :key="section.heading" class="equipment-source-section"><template v-for="(block,index) in section.blocks" :key="index"><div v-if="block.type==='table'" class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div></template></section></div></section>
            <section class="rule-page-section equipment-rule-section"><h2>Armor &amp; Shields</h2><h3>Armor</h3><div class="rule-table-wrap equipment-profile-table"><table class="rule-source-table equipment-stat-table"><thead><tr><th>Armor</th><th>Might</th><th>Guts</th><th>Mana Syphon</th><th>Armor Penalty</th><th>Weight</th><th>Cost</th></tr></thead><tbody><template v-for="group in armorTableGroups" :key="group.label"><tr class="equipment-group-row"><th colspan="7">{{ group.label }}</th></tr><tr v-for="row in group.items" :key="row.item.name"><td>{{ row.item.name }}</td><td>{{ row.profile.might }}</td><td>{{ row.profile.guts }}</td><td>{{ row.profile.mana }}</td><td>{{ row.profile.armorPenalty }}</td><td>{{ row.profile.weight }}</td><td>{{ row.item.costText }}</td></tr></template></tbody></table></div><h3>Shields</h3><div class="rule-table-wrap equipment-profile-table"><table class="rule-source-table equipment-stat-table"><thead><tr><th>Shield</th><th>Might</th><th>Guts</th><th>Mana Syphon</th><th>Armor Penalty</th><th>Weight</th><th>Cost</th></tr></thead><tbody><tr class="equipment-group-row"><th colspan="7">Shields</th></tr><tr v-for="row in shieldTableRows" :key="row.item.name"><td>{{ row.item.name }}</td><td>{{ row.profile.might }}</td><td>{{ row.profile.guts }}</td><td>{{ row.profile.mana }}</td><td>{{ row.profile.armorPenalty }}</td><td>{{ row.profile.weight }}</td><td>{{ row.item.costText }}</td></tr></tbody></table></div><aside v-if="armorPenaltySection" class="rule-narrative-note watcher-note-panel equipment-rule-note"><strong>ARMOR PENALTY</strong><p v-if="structuredRule(armorPenaltyText).intro">{{ structuredRule(armorPenaltyText).intro }}</p><div class="rule-breakdown-grid armor-penalty-fields"><div v-for="field in structuredRule(armorPenaltyText).fields.filter(field=>field.label!=='EXAMPLE')" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div><div class="armor-penalty-example"><span><small>ARMOR</small><strong>Root Weave −2</strong></span><b>+</b><span><small>SHIELD</small><strong>Vinegrip −1</strong></span><b>=</b><span><small>TOTAL</small><strong>Armor Penalty −3</strong></span><p>Speed 6 → 3 · Whisperster condition −3</p></div></aside><aside v-if="breakValueSection" class="rule-narrative-note watcher-note-panel equipment-rule-note"><strong>BREAK VALUE</strong><p>{{ displayText(breakValueText) }}</p><div class="break-value-example"><span><small>BREAK VALUE</small><strong>5</strong></span><b>←</b><span><small>NATURAL STRIKE TOTAL</small><strong>3 or less</strong></span><b>→</b><span><small>RESULT</small><strong>Break −1 → 4</strong></span></div><small>At Break 0, the item’s listed effects are halved until it is repaired.</small></aside></section>
            <section class="rule-page-section equipment-rule-section"><h2>Threadpieces</h2><template v-for="section in threadpieceSections" :key="section.heading"><template v-for="(block,index) in section.blocks" :key="index"><p v-if="block.type==='paragraph'">{{ displayText(block.text) }}</p><div v-else class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div></template><ThreadpieceExchange v-if="section.heading==='Standard Exchange Rate'" :start-sp="exchangeExampleStartingSp" /></template><aside v-if="resaleSection" class="rule-narrative-note watcher-note-panel resale-rule-panel"><strong>SELLING TREASURE &amp; RESALE</strong><p v-for="line in sectionParagraphs(resaleSection)" :key="line">{{ displayText(line) }}</p></aside></section>
            <section class="rule-page-section equipment-rule-section"><h2>Adventuring Items</h2><p>Adventuring Items cover the practical supplies carried between encounters: travel gear, field kits, consumables, tools, trinkets, and other equipment that supports exploration and downtime. Open a category to compare the available items, prices, and current effects.</p><details v-for="group in equipmentGroups" :key="group" class="organized-rule-category card-surface equipment-category-panel"><summary><h3>{{ group }}</h3></summary><div class="organized-rule-category-body equipment-item-grid"><RuleFeatureCard v-for="item in equipmentItemsFor(group)" :key="item.name" :title="item.name" :badge="item.costText" tone-class="detail-tone-equipment" :fields="gearCardFields(item)"><p v-if="item.description">{{ item.description }}</p></RuleFeatureCard></div></details></section>
          </section>
        </template>

        <template v-else-if="page.slug==='beyond-character-creation'">
          <section class="rule-page-section-stack beyond-creation-page"><section class="rule-page-section"><h2>Experience</h2><p v-for="line in sectionParagraphs(beyondIntroSection).filter(line=>!xpMethods.some(item=>line===`${item.label}: ${item.body}`)&&line!==xpAverageLine)" :key="line">{{ displayText(line) }}</p><div class="xp-method-grid"><RuleFeatureCard v-for="(method,index) in xpMethods" :key="method.label" :title="method.label" subtitle="EARNING EXPERIENCE" :tone-class="xpMethodTones[index]||'detail-tone-spark'"><p>{{ method.body }}</p></RuleFeatureCard></div><p v-if="xpAverageLine" class="xp-average-line">{{ displayText(xpAverageLine) }}</p></section><section v-if="beyondSpendingSection" class="rule-page-section"><h2>Spending Experience</h2><div v-if="advancementSummaryTable" class="rule-table-wrap advancement-summary-table"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in advancementSummaryTable.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div><details v-if="advancementChartTables.length" class="organized-rule-category nested-rule-panel card-surface"><summary><h3>Advancement Charts</h3></summary><div class="organized-rule-category-body advancement-chart-stack"><section v-for="(table,index) in advancementChartTables" :key="index"><h4>{{ advancementChartTitles[index] }}</h4><div class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in table.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div></section></div></details></section></section>
        </template>

        <template v-else-if="page.slug==='to-damage'">
          <section class="rule-page-section-stack damage-rules-page">
            <section class="rule-page-section"><h2>Damage Type</h2><p v-for="line in sectionParagraphs(sectionByHeading('battle','DAMAGE'))" :key="line">{{ displayText(line) }}</p><div class="damage-stat-grid damage-stat-three"><RuleFeatureCard title="Melee Damage" subtitle="FURY" tone-class="type-touch" :fields="[{label:'ADDITION',value:'Fury (Might Rank)'}]" /><RuleFeatureCard title="Range Damage" subtitle="ACCURACY" tone-class="type-shoot" :fields="[{label:'ADDITION',value:'Accuracy (Agility Rank)'}]" /><RuleFeatureCard title="Spell Damage" subtitle="HEART" tone-class="type-magic" :fields="[{label:'ADDITION',value:'Heart (Bravery Rank)'}]" /></div></section>
            <section class="rule-page-section"><h2>Damage Category</h2><p>{{ displayText(sectionParagraphs(sectionByHeading('battle','DAMAGE CATEGORY'))[0]||'') }}</p><div class="damage-category-three"><RuleFeatureCard title="Standard" subtitle="DAMAGE CATEGORY" tone-class="detail-tone-equipment"><p>Apply the target’s full Guts. If no Damage Category is stated, the damage is Standard.</p></RuleFeatureCard><RuleFeatureCard title="Direct" subtitle="DAMAGE CATEGORY" tone-class="type-shoot"><p>Reduce the target’s Guts by half, rounding up, to a minimum of [1] Guts.</p></RuleFeatureCard><RuleFeatureCard title="Lethal" subtitle="DAMAGE CATEGORY" tone-class="detail-tone-deed"><p>Bypasses Guts, including Guts from equipment, unless a more specific rule states otherwise.</p></RuleFeatureCard></div><aside class="damage-heart-callout ongoing-damage-panel"><strong>SPELL HEART DAMAGE</strong><p>{{ SPELL_HEART_DAMAGE_RULE }}</p></aside><aside class="rule-narrative-note watcher-note-panel ongoing-damage-panel"><strong>ON-GOING · RECURRING QUALIFIER</strong><p>Keeps its stated category and is not modified by normal damage conditions unless otherwise stated.</p><p>Direct On-Going uses half Guts, Lethal On-Going bypasses Guts, and On-Going damage with no stated category uses full Guts as Standard damage.</p></aside></section>
            <section class="rule-page-section"><h2>To Guts</h2><p v-for="line in sectionParagraphs(sectionByHeading('battle','TO GUTS'))" :key="line">{{ displayText(line) }}</p><div class="damage-formula-graphic accented-soak" role="img" aria-label="Incoming Damage minus applicable Guts equals Health lost."><div class="damage-formula-row"><span><small>INCOMING</small><strong>11 Damage</strong></span><span class="formula-operator">−</span><span><small>DEFENSE</small><strong>5 Guts</strong></span><span class="formula-operator">=</span><span class="damage-formula-result"><small>RESULT</small><strong>6 Health Lost</strong></span></div></div></section>
            <section class="rule-page-section"><h2>Resistances &amp; Weakness</h2><p>{{ displayText(sectionParagraphs(sectionByHeading('battle','RESISTANCES & WEAKNESS'))[0]||'') }}</p><div class="resistance-rule-pair"><RuleFeatureCard title="Resistance" subtitle="DAMAGE TYPE" tone-class="detail-tone-heritage"><p>Resistance adds its value to the Guts available against matching damage after the Damage Category determines how much base Guts applies.</p><div class="resistance-math-example"><span><small>INCOMING</small><strong>9 Direct Fire</strong></span><b>→</b><span><small>DIRECT GUTS</small><strong>6 ÷ 2 = 3</strong></span><b>+</b><span><small>FIRE RESISTANCE</small><strong>+3</strong></span><b>=</b><span class="result"><small>FINAL GUTS</small><strong>6</strong></span></div></RuleFeatureCard><RuleFeatureCard title="Weakness" subtitle="DAMAGE TYPE" tone-class="detail-tone-deed"><p>Weakness subtracts its value from the Guts available against matching damage after the Damage Category is applied, to a minimum of 0 unless another rule says otherwise.</p><div class="resistance-math-example"><span><small>INCOMING</small><strong>9 Standard Cold</strong></span><b>→</b><span><small>STANDARD GUTS</small><strong>6</strong></span><b>−</b><span><small>COLD WEAKNESS</small><strong>2</strong></span><b>=</b><span class="result"><small>FINAL GUTS</small><strong>4</strong></span></div></RuleFeatureCard></div></section>
          </section>
        </template>

        <template v-else-if="page.slug==='health'">
          <section class="rule-page-section-stack health-rules-page">
            <section class="rule-page-section"><h2>Health Points</h2><p>{{ displayText(sectionParagraphs(sectionByHeading('battle','HEALTH'))[0]||'') }}</p><div class="health-pool-example" role="img" aria-label="Example thirty point Health pool with eight Health lost and twenty-two Health remaining."><div class="health-pool-grid"><span v-for="cell in 30" :key="cell" :class="{lost:cell>22,'health-last-breath':cell<=2,'health-critical':cell>2&&cell<=4,'health-wounded':cell>4&&cell<=8}" aria-hidden="true"></span></div><div class="health-pool-key"><strong>22 / 30 Health</strong><span>8 Health lost</span></div></div><p>{{ displayText(sectionParagraphs(sectionByHeading('battle','HEALTH'))[1]||'') }}</p><div class="health-state-graphic"><RuleFeatureCard title="Healthy" subtitle="9–30 HEALTH" tone-class="detail-tone-heritage"><p>No low-Health penalty.</p></RuleFeatureCard><RuleFeatureCard title="Wounded" subtitle="5–8 HEALTH" tone-class="health-tone-wounded"><p>Condition [-1] to all dice rolls.</p></RuleFeatureCard><RuleFeatureCard title="Critical" subtitle="3–4 HEALTH" tone-class="health-tone-critical"><p>Condition [-2] to all dice rolls.</p></RuleFeatureCard><RuleFeatureCard title="Last Breath" subtitle="1–2 HEALTH" tone-class="health-tone-last-breath"><p>Condition [-3] to all dice rolls.</p></RuleFeatureCard></div></section>
            <section class="rule-page-section"><h2>Healing</h2><p>{{ displayText(sectionParagraphs(sectionByHeading('battle','HEALING'))[0]||'') }}</p><div class="healing-example-card"><div class="healing-pool-row"><span class="health-lost-block">12 Health</span><b>+</b><span class="healing-adjustment-group"><span class="health-heal-block">Restore [+4]</span><span class="healing-condition-block">Healing Condition [-1]</span></span><b>=</b><span class="health-net-restore">Restore [+3]</span><b>→</b><span class="health-restored-block">15 Health</span></div><small>Apply conditions to the healing amount before recording restored Health, and never exceed maximum Health.</small></div><p>{{ displayText(sectionParagraphs(sectionByHeading('battle','HEALING'))[1]||'') }}</p></section>
            <section class="rule-page-section"><h2>Defeated</h2><p>{{ displayText(sectionParagraphs(sectionByHeading('battle','DEFEATED'))[0]||'') }}</p><aside class="rule-narrative-note watcher-note-panel fate-roll-panel"><strong>FATE ROLL</strong><p>{{ displayText(sectionParagraphs(sectionByHeading('battle','DEFEATED'))[1]||'').replace(/^FATE ROLL:\s*/i,'') }}</p><div class="fate-die-graphic"><span><small>1d10</small><strong>1–4</strong><em>+1 Fate Mark</em></span><span><small>1d10</small><strong>5–10</strong><em>Pass</em></span></div></aside><aside class="rule-narrative-note watcher-note-panel death-watcher-note"><strong>WATCHER’S NOTE</strong><p>{{ displayText(sectionParagraphs(sectionByHeading('battle','DEFEATED'))[2]||'') }}</p></aside></section>
            <section class="rule-page-section"><h2>Encounter Ends</h2><p v-for="line in sectionParagraphs(sectionByHeading('battle','ENCOUNTER ENDS'))" :key="line">{{ displayText(line) }}</p><div class="rule-link-buttons centered-rule-links encounter-end-links"><RouterLink class="secondary-button" to="/rules/read/monsters">See Monsters &amp; Characters</RouterLink><RouterLink class="secondary-button" to="/rules/read/beyond-character-creation">See Experience</RouterLink></div></section>
          </section>
        </template>

        <template v-else-if="page.slug==='faq'"><section class="rule-page-section-stack faq-reader"><article v-for="item in quickFaq" :key="item.q" class="rule-page-section faq-row"><h2>{{ item.q }}</h2><p>{{ item.a }}</p></article></section></template>
        <template v-else-if="page.slug==='changes-updates'"><section class="changes-reader rule-page-section-stack"><article class="rule-page-section changes-reader-intro"><h2>Changes &amp; Updates</h2><p>Game Updates record changes to Brambleheart rules. The newest update is expanded; earlier updates remain available below in reverse chronological order.</p></article><GameUpdateList /></section></template>

        <template v-else>
          <section v-if="page.note" class="rule-page-section rule-source-note"><h2>Source Note</h2><p>{{ displayText(page.note) }}</p></section>
          <section v-if="sourceSections.length" class="rule-page-section-stack">
            <article v-for="(entry,index) in sourceSections" :key="`${entry.document}-${entry.section.heading}-${index}`" class="rule-page-section source-rule-section" :class="{'example-source-card':isExampleHeading(entry.section.heading),'creation-step-section':isCharacterCreationStep(entry.section),'creation-path-step':creationGraphicStep(entry.section,6)}">
              <header v-if="isCharacterCreationStep(entry.section)" class="creation-step-heading"><span>{{ characterCreationStepParts(entry.section)?.number }}</span><div><h2>{{ characterCreationStepParts(entry.section)?.title }}</h2></div></header>
              <h2 v-else-if="entry.section.heading!=='Overview'">{{ displayText(entry.section.heading) }}</h2>
              <div v-if="loreIndex>=0&&index===0" class="rule-page-banner-placeholder anthro-rule-banner" :class="{empty:!currentBanner}" :style="currentBanner?{backgroundImage:`url(${currentBanner})`}:undefined" aria-hidden="true"></div>
              <div v-if="canonicalSlug==='character-creation'&&entry.section.heading==='CHARACTER CREATION'" class="creation-overview-flow"><p>{{ sectionParagraphs(entry.section)[0] }}</p><div><span><small>IDENTITY</small><strong>Species · Spark · Homeland · Faith · Oath</strong></span><b>→</b><span><small>CAPABILITIES</small><strong>Attributes · Path · Talents · Magic</strong></span><b>→</b><span><small>READY FOR PLAY</small><strong>Equipment · Languages · Review</strong></span></div><p>{{ sectionParagraphs(entry.section)[2] }}</p></div>
              <template v-for="(block,blockIndex) in entry.section.blocks" :key="blockIndex">
                <div v-if="keywordPartsForBlock(block).length" class="keyword-pill-row"><span v-for="keyword in keywordPartsForBlock(block)" :key="keyword" class="keyword-pill">{{ displayText(keyword) }}</span></div>
                <template v-else-if="block.type==='paragraph'&&!(page.slug==='spell-types-targeting'&&entry.section.heading==='SPELL KEYWORDS')&&!(canonicalSlug==='character-creation'&&entry.section.heading==='CHARACTER CREATION')"><div v-if="isDialogue(block.text)" class="dialogue-example-box"><p v-for="part in dialogueParts(block.text)" :key="`${part.actor}-${part.text}`"><strong>{{ part.actor }}:</strong> <span>{{ displayText(part.text) }}</span></p></div><div v-else-if="bulletParts(block.text).length" class="rule-bullet-block"><p>{{ bulletParts(block.text)[0] }}</p><ul><li v-for="part in bulletParts(block.text).slice(1)" :key="part"><template v-for="(segment,segmentIndex) in optionalTextParts(part)" :key="segmentIndex"><em v-if="segment.optional">{{ segment.text }}</em><span v-else>{{ segment.text }}</span></template></li></ul></div><p v-else :class="{'example-copy':isExampleHeading(entry.section.heading)}"><strong v-if="labeledParagraph(block.text).label" class="rule-inline-label">{{ labeledParagraph(block.text).label }}:</strong><template v-for="(part,partIndex) in bracketParts(labeledParagraph(block.text).body)" :key="partIndex"><strong v-if="part.bold" class="bracket-number">{{ part.text }}</strong><span v-else>{{ part.text }}</span></template></p></template>
                <section v-else-if="isCharacterCreationAttributeTable(entry.section,block)" class="creation-attribute-demo"><header><strong>Spend 5 Points</strong><span>{{ creationAttributePointsRemaining }} points remaining</span></header><div class="creation-attribute-list"><article v-for="attribute in attributes" :key="attribute.id" class="creation-attribute-row" :class="`attribute-${attribute.id}`"><div class="creation-attribute-copy"><h3>{{ attribute.name }}</h3><p>{{ attribute.description }}</p><div class="creation-secondary-stats"><span v-for="secondary in creationAttributeSecondary(attribute.id)" :key="secondary.label"><small>{{ secondary.label }}</small><strong>{{ secondary.value }}</strong></span></div></div><div class="creation-attribute-controls"><div class="creation-rank-summary"><span><small>Rank</small><strong>{{ creationAttributeRanks[attribute.id] }}</strong></span><span><small>Modifier</small><strong>+{{ creationAttributeModifier(attribute.id) }}</strong></span></div><div class="creation-rank-stepper"><button type="button" :disabled="creationAttributeRanks[attribute.id]<=1" :aria-label="`Decrease ${attribute.name}`" @click="adjustCreationAttribute(attribute.id,-1)">−</button><strong>{{ creationAttributeRanks[attribute.id] }}</strong><button type="button" :disabled="creationAttributeRanks[attribute.id]>=3||creationAttributePointsRemaining<=0" :aria-label="`Increase ${attribute.name}`" @click="adjustCreationAttribute(attribute.id,1)">+</button></div></div></article></div><small class="creation-demo-note">Rules-reader example only. These values reset when you leave this page or reload.</small></section>
                <div v-else-if="block.type==='table'&&block.rows.length===1&&block.rows[0].length===1&&isDialogue(block.rows[0][0])" class="dialogue-example-box"><p v-for="part in dialogueParts(block.rows[0][0])" :key="`${part.actor}-${part.text}`"><strong>{{ part.actor }}:</strong> <span>{{ displayText(part.text) }}</span></p></div>
                <article v-else-if="isBuildingSeluTable(block)" class="creation-example rule-selu-example"><strong>Building Selu:</strong> <span>{{ singleCellText(block).replace(/^Selu(?:’s| of the Wandering Reeds)?\s*/i,'Selu ') }}</span></article>
                <article v-else-if="skillTreeName(block)" class="skill-tree-card" :class="`skill-tree-${skillTreeTone(skillTreeName(block))}`"><header><h3>{{ skillTreeName(block).replace(/\s+Skill Tree$/i,' - Skill Tree') }}</h3><div class="skill-tree-column-headings"><small>Skill</small><small>Description</small><small>Example</small></div></header><div class="skill-tree-list"><div v-for="(row,rowIndex) in skillTreeRows(block)" :key="rowIndex"><strong>{{ displayText(row[0]||'') }}</strong><span>{{ displayText(row[1]||'') }}</span><small>{{ displayText(row[2]||'') }}</small></div></div></article>
                <article v-else-if="singleCellText(block)&&isLongNarrativeHeading(singleCellText(block))" class="rule-narrative-note"><strong>{{ narrativeParts(singleCellText(block)).title }}</strong><p>{{ narrativeParts(singleCellText(block)).body }}</p></article>
                <h3 v-else-if="singleCellText(block)" class="source-table-title">{{ singleCellText(block) }}</h3>
                <div v-else-if="equipmentTableRows(block).length" class="equipment-rule-card-grid"><article v-for="item in equipmentTableRows(block)" :key="`${item.name}-${blockIndex}`" class="equipment-rule-card detail-tone-equipment"><header><strong>{{ item.name }}</strong></header><div><span v-for="field in item.fields" :key="field.label"><small>{{ field.label }}</small><template v-for="(part,partIndex) in bracketParts(field.value)" :key="partIndex"><strong v-if="part.bold" class="bracket-number">{{ part.text }}</strong><b v-else>{{ part.text }}</b></template></span></div></article></div>
                <div v-else-if="block.type==='table'" class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex"><template v-for="(part,partIndex) in bracketParts(cell)" :key="partIndex"><strong v-if="part.bold" class="bracket-number">{{ part.text }}</strong><span v-else>{{ part.text }}</span></template></td></tr></tbody></table></div>
              </template>
              <div v-if="creationGraphicStep(entry.section,1)" class="creation-reference-graphic creation-trait-graphic"><RuleFeatureCard title="Heritage Traits" subtitle="INHERITED" tone-class="detail-tone-heritage"><p>Innate features of your chosen Species.</p></RuleFeatureCard><RuleFeatureCard title="Cultural Traits" subtitle="LEARNED" tone-class="detail-tone-culture"><p>Learned traditions that may be exchanged during Character Creation.</p></RuleFeatureCard></div>
              <div v-if="creationGraphicStep(entry.section,2)" class="creation-reference-graphic creation-example-pair"><RuleFeatureCard v-if="creationSparkExample" :title="creationSparkExample.name" subtitle="SPARK" tone-class="detail-tone-spark"><p>{{ creationSparkExample.description }}</p><template #footer><div class="keyword-pill-row"><span v-for="keyword in creationSparkExample.keywords" :key="keyword" class="keyword-pill">{{ keyword }}</span></div></template></RuleFeatureCard><RuleFeatureCard v-if="creationDeedExample" class="creation-deed-example" :title="creationDeedExample.name" subtitle="DEED" tone-class="detail-tone-deed" :fields="[{label:'OBJECTIVE',value:creationDeedExample.objective},{label:'REWARD',value:creationDeedExample.reward}]"><template #footer><div class="keyword-pill-row"><span v-for="keyword in creationDeedExample.keywords" :key="keyword" class="keyword-pill">{{ keyword }}</span></div></template></RuleFeatureCard></div>
              <div v-if="creationGraphicStep(entry.section,3)" class="creation-reference-graphic creation-single-example"><RuleFeatureCard :title="creationHomelandExample.name" subtitle="HOMELAND" tone-class="detail-tone-homeland"><p>Begins with two Skills at Rank 1.</p><template #footer><div class="keyword-pill-row"><span v-for="skill in creationHomelandExample.skills" :key="skill" class="keyword-pill">{{ skill }} · Rank 1</span></div></template></RuleFeatureCard></div>
              <div v-if="creationGraphicStep(entry.section,4)" class="creation-reference-graphic creation-example-pair"><RuleFeatureCard :title="creationFaithExample" subtitle="FAITH" tone-class="detail-tone-faith"><p>A belief tradition that frames meaning, ritual, and belonging.</p></RuleFeatureCard><RuleFeatureCard :title="creationOathExample[0]" subtitle="OATH" tone-class="detail-tone-oath"><p>{{ creationOathExample[1] }}</p></RuleFeatureCard></div>
              <div v-if="creationGraphicStep(entry.section,6)" class="creation-path-reference"><div class="path-choice-grid"><article v-for="path in startingPathOptions" :key="path.id" class="path-choice-card creation-path-card" :class="`path-${path.id}`" aria-disabled="true"><span class="path-choice-kicker">{{ path.kicker }}</span><strong class="path-choice-title">{{ path.title }}</strong><p>{{ path.description }}</p></article></div></div>
              <div v-if="creationGraphicStep(entry.section,7)" class="creation-equipment-graphic"><RouterLink class="secondary-button equipment-reference-link" to="/rules/read/adventuring-gear">Equipment &amp; Gear</RouterLink><ThreadpieceExchange :start-sp="exchangeExampleStartingSp" /></div>
              <aside v-if="creationGraphicStep(entry.section,8)" class="rule-narrative-note watcher-note-panel"><strong>WATCHER’S NOTE</strong><p>Some campaigns may require character details that are optional in the character creation rules, or may ask for additional information that ties a hero to the campaign. Always check with your Watcher before play to confirm which character details are required at your table.</p></aside>
            </article>
          </section>
          <section v-else-if="!page.note" class="empty-state card-surface compact-empty"><h2>Rule Text Unavailable</h2><p>This page is organized in the reader but has no supplied source text in the current rules package.</p></section>
        </template>

  </RulePageLayout>
  <RulePageLayout v-else title="Rule Not Found" section="Rules" summary="The requested rule page is not available." back-to="/rules" back-label="Back to Rules" prefer-back-to>
    <section class="empty-state compact-empty"><h2>Rule Not Found</h2><p>The requested rule page is not available.</p><RouterLink class="primary-button" to="/rules">Back to Rules</RouterLink></section>
  </RulePageLayout>
</template>

<style scoped>
